                  <input id="q3-csharp" name="question-3" type="checkbox" value="C#">
                  <span class="choice-text">C#</span>
                </label>
              </div>
              <p class="field-message error" id="question-3-error" hidden>Error: Select at least one answer for question 3.</p>
              <p class="field-message feedback" id="question-3-feedback" hidden></p>
            </fieldset>
