  </div>

  <script>
    const answerKey = {
      "question-1": ["C", "Rust"],
      "question-2": ["HTML", "XML", "Markdown"],
      "question-3": ["Go", "TypeScript", "C#"]
    };

    const form = document.getElementById("quiz-form");
    const resultMessage = document.getElementById("quiz-results");

    function getCheckedValues(name) {
      return Array.from(form.querySelectorAll(`input[name="${name}"]:checked`)).map((input) => input.value);
    }

    function sameAnswers(selectedValues, correctValues) {
      if (selectedValues.length !== correctValues.length) {
        return false;
      }

      const selectedSet = new Set(selectedValues);
      return correctValues.every((value) => selectedSet.has(value));
    }

    function clearFieldError(fieldset, questionName) {
      fieldset.classList.remove("invalid");
      const error = document.getElementById(`${questionName}-error`);
      error.hidden = true;
    }

    function showFieldError(fieldset, questionName) {
      fieldset.classList.add("invalid");
      const error = document.getElementById(`${questionName}-error`);
      error.hidden = false;
    }

    function setFeedback(questionName, isCorrect, correctAnswers) {
      const feedback = document.getElementById(`${questionName}-feedback`);
      feedback.hidden = false;
      feedback.classList.toggle("is-incorrect", !isCorrect);
      feedback.innerHTML = isCorrect
        ? "<strong>Correct.</strong> Nice work."
        : `<strong>Not quite.</strong> Correct answers: ${correctAnswers.join(", ")}.`;
    }

    Object.keys(answerKey).forEach((questionName) => {
      const fieldset = document.getElementById(questionName);
      const inputs = form.querySelectorAll(`input[name="${questionName}"]`);

      inputs.forEach((input) => {
        input.addEventListener("change", () => {
          if (getCheckedValues(questionName).length > 0) {
            clearFieldError(fieldset, questionName);
          }
        });
      });
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      let score = 0;
      let firstInvalidInput = null;

      Object.entries(answerKey).forEach(([questionName, correctAnswers]) => {
        const fieldset = document.getElementById(questionName);
        const selectedValues = getCheckedValues(questionName);

        if (selectedValues.length === 0) {
          showFieldError(fieldset, questionName);
          document.getElementById(`${questionName}-feedback`).hidden = true;

          if (!firstInvalidInput) {
            firstInvalidInput = form.querySelector(`input[name="${questionName}"]`);
          }
          return;
        }

        clearFieldError(fieldset, questionName);

        const isCorrect = sameAnswers(selectedValues, correctAnswers);
        if (isCorrect) {
          score += 1;
        }

        setFeedback(questionName, isCorrect, correctAnswers);
      });

      if (firstInvalidInput) {
        resultMessage.textContent = "Please answer every question before checking your score.";
        firstInvalidInput.focus();
        return;
      }

      const totalQuestions = Object.keys(answerKey).length;
      resultMessage.textContent = `You scored ${score} out of ${totalQuestions}.`;
    });
  </script>
