       padding: 0.75rem 1rem;
       border-radius: 999px;
       background: var(--primary);
       color: #ffffff;
       text-decoration: none;
       transform: translateY(-220%);
       transition: transform 0.2s ease;
       z-index: 10;
     }

     .skip-link:focus {
       transform: translateY(0);
     }

     .sr-only {
       position: absolute;
       width: 1px;
       height: 1px;
       padding: 0;
       margin: -1px;
       overflow: hidden;
       clip: rect(0, 0, 0, 0);
       white-space: nowrap;
       border: 0;
     }

     .page-shell {
       width: min(100%, 72rem);
       margin: 0 auto;
       padding: 2rem 1rem 4rem;
     }

     .hero {
       padding: 1rem 0 2rem;
     }

     .eyebrow {
       display: inline-flex;
       align-items: center;
       gap: 0.5rem;
       padding: 0.45rem 0.8rem;
       border-radius: 999px;
       background: rgba(52, 87, 246, 0.1);
       color: var(--primary-strong);
       font-size: 0.95rem;
       font-weight: 700;
       letter-spacing: 0.01em;
     }

     h1 {
       margin: 1rem 0 0.75rem;
       font-size: clamp(2rem, 4vw, 3.75rem);
       line-height: 1.05;
       letter-spacing: -0.03em;
     }

     .hero p {
       max-width: 42rem;
       margin: 0;
       color: var(--muted);
       font-size: 1.05rem;
     }

     .quiz-card {
       padding: clamp(1.25rem, 3vw, 2rem);
       border: 1px solid var(--border);
       border-radius: var(--radius-lg);
       background: var(--surface);
       backdrop-filter: blur(18px);
       box-shadow: var(--shadow);
     }

     form {
       display: grid;
       gap: 1.25rem;
     }

     .form-field {
       padding: 1.25rem;
       border: 1px solid var(--border);
       border-radius: var(--radius-md);
       background: var(--surface-strong);
     }

     fieldset {
       margin: 0;
       padding: 0;
       border: 0;
       min-width: 0;
     }

     legend {
       padding: 0;
       margin-bottom: 0.55rem;
       font-size: 1.12rem;
       font-weight: 700;
     }

     .question-intro {
       margin: 0 0 0.85rem;
       color: var(--muted);
       font-size: 0.96rem;
     }

     .choice-list {
       display: grid;
       gap: 0.75rem;
     }

     .choice {
       display: flex;
       align-items: flex-start;
       gap: 0.85rem;
       padding: 0.9rem 1rem;
       border: 1px solid var(--border);
       border-radius: var(--radius-sm);
       background: #fbfcff;
       cursor: pointer;
       transition: border-color 0.2s ease, transform 0.2s ease, box-shadow 0.2s ease;
     }

     .choice:hover {
       border-color: rgba(52, 87, 246, 0.35);
       transform: translateY(-1px);
     }

     .choice input {
       width: 1.15rem;
       height: 1.15rem;
       margin-top: 0.15rem;
       accent-color: var(--primary);
       flex: 0 0 auto;
     }

     .choice-text {
       font-weight: 600;
     }

     .field-message {
       margin: 0.9rem 0 0;
       font-size: 0.95rem;
     }

     .error {
       color: var(--error);
       font-weight: 600;
     }

     .feedback {
       color: var(--muted);
     }

     .feedback strong {
       color: var(--success);
     }

     .feedback.is-incorrect strong {
       color: var(--error);
     }

     .actions {
       display: flex;
       flex-wrap: wrap;
       gap: 1rem;
       align-items: center;
       justify-content: space-between;
       margin-top: 0.5rem;
     }

     button {
       border: 0;
       border-radius: 999px;
       padding: 0.95rem 1.35rem;
       background: linear-gradient(135deg, var(--primary) 0%, var(--primary-strong) 100%);
       color: #ffffff;
       font: inherit;
       font-weight: 700;
       cursor: pointer;
       box-shadow: 0 18px 30px rgba(52, 87, 246, 0.26);
     }

     .results {
       flex: 1 1 18rem;
       min-height: 1.5rem;
       color: var(--text);
       font-weight: 600;
     }

     :focus-visible {
       outline: 3px solid rgba(52, 87, 246, 0.42);
       outline-offset: 3px;
     }

     .invalid {
       border-color: rgba(201, 53, 71, 0.4);
       box-shadow: inset 0 0 0 1px rgba(201, 53, 71, 0.15);
     }

     @media (max-width: 42rem) {
       .page-shell {
         padding-inline: 0.85rem;
       }

       .quiz-card,
       .form-field {
         padding: 1rem;
       }

       .actions {
         align-items: stretch;
       }

       button {
         width: 100%;
       }
     }

     @media (prefers-reduced-motion: reduce) {
       *,
       *::before,
       *::after {
         scroll-behavior: auto !important;
         transition: none !important;
       }
     }

     @media (forced-colors: active) {
       .quiz-card,
       .form-field,
       .choice,
       button {
         border: 1px solid ButtonText;
         box-shadow: none;
       }

       button {
         background: ButtonFace;
         color: ButtonText;
       }
     }
   </style>
 </head>
 <body>
   <a class="skip-link" href="#maincontent">Skip to main content</a>

   <div class="page-shell">
     <header class="hero">
       <span class="eyebrow">Interactive quiz</span>
       <h1>Test your knowledge of computer languages</h1>
       <p>Each question can have more than one correct answer. Pick every option you believe fits, then check your score.</p>
     </header>

     <main id="maincontent" tabindex="-1">
       <section class="quiz-card" aria-labelledby="quiz-heading">
         <h2 id="quiz-heading">Three quick questions</h2>

         <form id="quiz-form" novalidate>
           <div class="form-field">
             <fieldset id="question-1" aria-describedby="question-1-help question-1-error">
               <legend>1. Which of these are compiled programming languages? <span aria-hidden="true">*</span><span class="sr-only"> required</span></legend>
               <p class="question-intro" id="question-1-help">Select all that apply. Choose at least one answer. Compiled languages are commonly translated to native machine code before running.</p>
               <div class="choice-list">
                 <label class="choice" for="q1-c">
                   <input id="q1-c" name="question-1" type="checkbox" value="C">
                   <span class="choice-text">C</span>
                 </label>
                 <label class="choice" for="q1-rust">
                   <input id="q1-rust" name="question-1" type="checkbox" value="Rust">
                   <span class="choice-text">Rust</span>
                 </label>
                 <label class="choice" for="q1-python">
                   <input id="q1-python" name="question-1" type="checkbox" value="Python">
                   <span class="choice-text">Python</span>
                 </label>
                 <label class="choice" for="q1-javascript">
                   <input id="q1-javascript" name="question-1" type="checkbox" value="JavaScript">
                   <span class="choice-text">JavaScript</span>
                 </label>
               </div>
               <p class="field-message error" id="question-1-error" hidden>Error: Select at least one answer for question 1.</p>
               <p class="field-message feedback" id="question-1-feedback" hidden></p>
             </fieldset>
           </div>

           <div class="form-field">
             <fieldset id="question-2" aria-describedby="question-2-help question-2-error">
               <legend>2. Which of these are markup languages? <span aria-hidden="true">*</span><span class="sr-only"> required</span></legend>
               <p class="question-intro" id="question-2-help">Select all that apply. Choose at least one answer.</p>
               <div class="choice-list">
                 <label class="choice" for="q2-html">
                   <input id="q2-html" name="question-2" type="checkbox" value="HTML">
                   <span class="choice-text">HTML</span>
                 </label>
                 <label class="choice" for="q2-xml">
                   <input id="q2-xml" name="question-2" type="checkbox" value="XML">
                   <span class="choice-text">XML</span>
                 </label>
                 <label class="choice" for="q2-java">
                   <input id="q2-java" name="question-2" type="checkbox" value="Java">
                   <span class="choice-text">Java</span>
                 </label>
                 <label class="choice" for="q2-markdown">
                   <input id="q2-markdown" name="question-2" type="checkbox" value="Markdown">
                   <span class="choice-text">Markdown</span>
                 </label>
               </div>
               <p class="field-message error" id="question-2-error" hidden>Error: Select at least one answer for question 2.</p>
               <p class="field-message feedback" id="question-2-feedback" hidden></p>
             </fieldset>
           </div>

           <div class="form-field">
             <fieldset id="question-3" aria-describedby="question-3-help question-3-error">
               <legend>3. Which of these are statically typed languages in common use? <span aria-hidden="true">*</span><span class="sr-only"> required</span></legend>
               <p class="question-intro" id="question-3-help">Select all that apply. Choose at least one answer.</p>
               <div class="choice-list">
                 <label class="choice" for="q3-go">
                   <input id="q3-go" name="question-3" type="checkbox" value="Go">
                   <span class="choice-text">Go</span>
                 </label>
                 <label class="choice" for="q3-typescript">
                   <input id="q3-typescript" name="question-3" type="checkbox" value="TypeScript">
                   <span class="choice-text">TypeScript</span>
                 </label>
                 <label class="choice" for="q3-ruby">
                   <input id="q3-ruby" name="question-3" type="checkbox" value="Ruby">
                   <span class="choice-text">Ruby</span>
                 </label>
                 <label class="choice" for="q3-csharp">
                   <input id="q3-csharp" name="question-3" type="checkbox" value="C#">
                   <span class="choice-text">C#</span>
                 </label>
               </div>
               <p class="field-message error" id="question-3-error" hidden>Error: Select at least one answer for question 3.</p>
               <p class="field-message feedback" id="question-3-feedback" hidden></p>
             </fieldset>
           </div>

           <div class="actions">
             <button type="submit">Check answers</button>
             <p class="results" id="quiz-results" role="status" aria-live="polite"></p>
           </div>
         </form>
       </section>
     </main>
   </div>

   <script>
     const answerKey = {
       "question-1": ["C", "Rust"],
       "question-2": ["HTML", "XML", "Markdown"],
       "question-3": ["Go", "TypeScript", "C#"]
     };

     const form = document.getElementById("quiz-form");
     const resultMessage = document.getElementById("quiz-results");

     function getCheckedValues(name) {
       return Array.from(form.querySelectorAll(`input[name="${name}"]:checked`)).map((input) => input.value);
     }

     function sameAnswers(selectedValues, correctValues) {
       if (selectedValues.length !== correctValues.length) {
         return false;
       }

       const selectedSet = new Set(selectedValues);
       return correctValues.every((value) => selectedSet.has(value));
     }

     function clearFieldError(fieldset, questionName) {
       fieldset.classList.remove("invalid");
       const error = document.getElementById(`${questionName}-error`);
       error.hidden = true;
     }

     function showFieldError(fieldset, questionName) {
       fieldset.classList.add("invalid");
       const error = document.getElementById(`${questionName}-error`);
       error.hidden = false;
     }

     function setFeedback(questionName, isCorrect, correctAnswers) {
       const feedback = document.getElementById(`${questionName}-feedback`);
       feedback.hidden = false;
       feedback.classList.toggle("is-incorrect", !isCorrect);
       feedback.innerHTML = isCorrect
         ? "<strong>Correct.</strong> Nice work."
         : `<strong>Not quite.</strong> Correct answers: ${correctAnswers.join(", ")}.`;
     }

     Object.keys(answerKey).forEach((questionName) => {
       const fieldset = document.getElementById(questionName);
       const inputs = form.querySelectorAll(`input[name="${questionName}"]`);

       inputs.forEach((input) => {
         input.addEventListener("change", () => {
           if (getCheckedValues(questionName).length > 0) {
             clearFieldError(fieldset, questionName);
           }
         });
       });
     });

     form.addEventListener("submit", (event) => {
       event.preventDefault();

       let score = 0;
       let firstInvalidInput = null;

       Object.entries(answerKey).forEach(([questionName, correctAnswers]) => {
         const fieldset = document.getElementById(questionName);
         const selectedValues = getCheckedValues(questionName);

         if (selectedValues.length === 0) {
           showFieldError(fieldset, questionName);
           document.getElementById(`${questionName}-feedback`).hidden = true;

           if (!firstInvalidInput) {
             firstInvalidInput = form.querySelector(`input[name="${questionName}"]`);
           }
           return;
         }

         clearFieldError(fieldset, questionName);

         const isCorrect = sameAnswers(selectedValues, correctAnswers);
         if (isCorrect) {
           score += 1;
         }

         setFeedback(questionName, isCorrect, correctAnswers);
       });

       if (firstInvalidInput) {
         resultMessage.textContent = "Please answer every question before checking your score.";
         firstInvalidInput.focus();
         return;
       }

       const totalQuestions = Object.keys(answerKey).length;
       resultMessage.textContent = `You scored ${score} out of ${totalQuestions}.`;
     });
   </script>
 </body>
 </html>

')
